net.coobird.thumbnailator.util.exif.IfdStructure ifdValue = 
    new net.coobird.thumbnailator.util.exif.IfdStructure(0x0112, 3, 1, 8);

int val = -1;
if (ifdValue.isValue()) {
    val = ifdValue.getOffsetValue();
} else if (ifdValue.isOffset()) {
    throw new AssertionError("Expected to be a value, not an offset");
}

net.coobird.thumbnailator.util.exif.IfdStructure ifdOffset = 
    new net.coobird.thumbnailator.util.exif.IfdStructure(0x0110, 2, 10, 2048);

int offset = -1;
if (ifdOffset.isOffset()) {
    offset = ifdOffset.getOffsetValue();
} else if (ifdOffset.isValue()) {
    throw new AssertionError("Expected to be an offset, not a value");
}

assert val == 8 : "Value should be 8";
assert offset == 2048 : "Offset should be 2048";

System.out.println("__CHECK__ getOffsetValue " + val + "-" + offset);

